import subprocess
def run(args, inp=None):
    r=subprocess.run(["./executable","-d","fonts"]+args, input=inp, capture_output=True)
    return r.stdout
def glyph(code):
 lines=open('fonts/standard.flf').read().splitlines()
 idx=16+(code-32)*6
 return [l[:-1] if i<5 else l[:-2] for i,l in enumerate(lines[idx:idx+6])]
for ch in "ABCDEFGHIJabcd!|/_ ()[]{}":
  for mode in [["-W"],["-k"]]:
    out=run(mode, ch.encode()).decode().splitlines()
    print(ch, mode, len(out[0]), out)
  print(" glyph", glyph(ord(ch)), [len(x) for x in glyph(ord(ch))])
PY"}

