import pty, os, subprocess, fcntl, termios, struct
def run(cols, which):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0,0))
    if which=="stdin":
        p=subprocess.Popen(["/workspace/executable","-t","-I4"], stdin=slave, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd="/workspace")
    elif which=="stdout":
        p=subprocess.Popen(["/workspace/executable","-t","-I4"], stdin=subprocess.PIPE, stdout=slave, stderr=subprocess.PIPE, cwd="/workspace")
    elif which=="stderr":
        p=subprocess.Popen(["/workspace/executable","-t","-I4"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=slave, cwd="/workspace")
    elif which=="all":
        p=subprocess.Popen(["/workspace/executable","-t","-I4"], stdin=slave, stdout=slave, stderr=slave, cwd="/workspace")
    os.close(slave)
    out,err=p.communicate(b"")
    os.close(master)
