{"command":"python3 << 'PY'
import pty, os, subprocess, fcntl, termios, struct, select
def makepty(cols):
 m,s=pty.openpty(); fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols,0,0)); return m,s
def read_all(fds, proc):
 out={fd:b"" for fd in fds}
 while proc.poll() is None or any(fds):
   r,_,_=select.select(fds,[],[],0.5)
   if not r:
      if proc.poll() is not None: break
      continue
   for fd in r:
     try: d=os.read(fd,4096)
     except OSError: d=b""
     if d: out[fd]+=d
     else: fds.remove(fd)
 return out
for stdin_cols, stdout_cols in [(40,99),(99,40),(0,40),(40,0)]:
 mi,si=makepty(stdin_cols); mo,so=makepty(stdout_cols)
 p=subprocess.Popen(["/workspace/executable","-t","-I4"], stdin=si, stdout=so, stderr=subprocess.PIPE, cwd="/workspace")
 os.close(si); os.close(so)
 outs=read_all([mo],p)
 err=p.stderr.read(); p.wait(); os.close(mi); os.close(mo)
 print(stdin_cols,stdout_cols,outs,err,p.returncode)
 # stty size to verify stdin pty cols via fd0: run /usr/bin/stty size with stdin pty
PY"}

