# build probe font
lines=["flf2a$ 1 1 20 15 0"]
for code in range(32,127): lines.append(f"[{code}]@@")
for i,dc in enumerate([196,214,220,228,246,252,223]): lines.append(f"[D{dc}]@@")
for code in range(0,1024):
 if 32<=code<127: continue
 lines.append(f"0x{code:x}"); lines.append(f"[{code}]@@")
# also negative tags -1..-10
