#!/usr/bin/env python3
import os
import sys
import io
import zlib
import zipfile
import struct

try:
    import fcntl
    import termios
except Exception:  # pragma: no cover
    fcntl = None
    termios = None

VERSION_INT = 20205
DEFAULT_FONT_DIR = b"/usr/local/share/figlet"
DEFAULT_FONT_NAME = b"standard"

WS_BYTES = b" \t\n\v\f\r"


def c_atoi(data):
    """Emulate C atoi on a byte string (strtol base 10, cast to int)."""
    if isinstance(data, str):
        data = data.encode()
    i = 0
    n = len(data)
    while i < n and data[i] in WS_BYTES:
        i += 1
    sign = 1
    if i < n and data[i:i + 1] in (b"+", b"-"):
        if data[i:i + 1] == b"-":
            sign = -1
        i += 1
    start = i
    val = 0
    while i < n and 48 <= data[i] <= 57:
        val = val * 10 + (data[i] - 48)
        i += 1
    if i == start:
        return 0
    val *= sign
    # strtol saturation on 64-bit long
    if val > 9223372036854775807:
        val = 9223372036854775807
    if val < -9223372036854775808:
        val = -9223372036854775808
    # cast to 32-bit int
    val &= 0xFFFFFFFF
    if val >= 0x80000000:
        val -= 0x100000000
    return val


def strip_suffix(name, suffixes):
    low = name.lower()
    for suf in suffixes:
        if len(name) >= len(suf) and low.endswith(suf):
            return name[:-len(suf)]
    return name


class ProgramExit(Exception):
    def __init__(self, code):
        self.code = code


class Renderer(object):
    pass


# ---------------------------------------------------------------------------
# Font handling

class Glyph(object):
    __slots__ = ("rows", "width")

    def __init__(self, rows):
        self.rows = rows
        w = 0
        for r in rows:
            if len(r) > w:
                w = len(r)
        self.width = w


class Font(object):
    def __init__(self):
        self.hardblank = 36
        self.height = 0
        self.old_layout = 0
        self.print_direction = 0
        self.full_layout = None
        self.glyphs = {}
        self.deutsch = {}
        self.is_tlf = False


class LineReader(object):
    def __init__(self, data, is_tlf):
        self.data = data
        self.is_tlf = is_tlf
        self.pos = 0

    def has_more(self):
        return self.pos < len(self.data)

    def next_line(self):
        if self.pos >= len(self.data):
            return None
        idx = self.data.find(b"\n", self.pos)
        if idx < 0:
            raw = self.data[self.pos:]
            self.pos = len(self.data)
        else:
            raw = self.data[self.pos:idx]
            self.pos = idx + 1
        if self.is_tlf:
            return raw.decode("utf-8", "surrogateescape")
        return raw


def parse_ints_bytes(data, start, limit=8):
    ints = []
    i = start
    n = len(data)
    while len(ints) < limit:
        while i < n and data[i] in WS_BYTES:
            i += 1
        if i >= n:
            break
        j = i
        if data[j:j + 1] in (b"+", b"-"):
            j += 1
        if j >= n or not (48 <= data[j] <= 57):
            break
        while j < n and 48 <= data[j] <= 57:
            j += 1
        v = c_atoi(data[i:j])
        ints.append(v)
        i = j
    return ints


def parse_ints_text(text, start, limit=8):
    ints = []
    i = start
    n = len(text)
    ws = " \t\n\v\f\r"
    while len(ints) < limit:
        while i < n and text[i] in ws:
            i += 1
        if i >= n:
            break
        j = i
        if text[j] in "+-":
            j += 1
        if j >= n or not text[j].isdigit():
            break
        while j < n and text[j].isdigit():
            j += 1
        ints.append(c_atoi(text[i:j].encode()))
        i = j
    return ints


def strip_glyph_line_bytes(line):
    end = len(line)
    while end > 0 and line[end - 1] in b" \t\v\f\r":
        end -= 1
    line = line[:end]
    if not line:
        return []
    endchar = line[-1]
    end = len(line)
    while end > 0 and line[end - 1] == endchar:
        end -= 1
    return list(line[:end])


def strip_glyph_line_text(line):
    s = line.rstrip(" \t\v\f\r")
    if not s:
        return []
    endchar = s[-1]
    end = len(s)
    while end > 0 and s[end - 1] == endchar:
        end -= 1
    return [ord(ch) for ch in s[:end]]


def parse_c_code_token_bytes(line):
    """Parse an integer at the start of a font code line (sscanf %i style)."""
    i = 0
    n = len(line)
    while i < n and line[i] in WS_BYTES:
        i += 1
    if i >= n:
        return 0
    sign = 1
    if line[i:i + 1] in (b"+", b"-"):
        if line[i:i + 1] == b"-":
            sign = -1
        i += 1
    if i + 1 < n and line[i:i + 1] == b"0" and line[i + 1:i + 2] in (b"x", b"X"):
        j = i + 2
        val = 0
        found = False
        while j < n:
            c = line[j]
            if 48 <= c <= 57:
                d = c - 48
            elif 65 <= c <= 70:
                d = c - 55
            elif 97 <= c <= 102:
                d = c - 87
            else:
                break
            val = val * 16 + d
            found = True
            j += 1
        return sign * val if found else 0
    if i < n and line[i:i + 1] == b"0":
        # octal
        j = i
        val = 0
        while j < n and 48 <= line[j] <= 55:
            val = val * 8 + (line[j] - 48)
            j += 1
        return sign * val
    j = i
    val = 0
    found = False
    while j < n and 48 <= line[j] <= 57:
        val = val * 10 + (line[j] - 48)
        found = True
        j += 1
    return sign * val if found else 0


def parse_c_code_token_text(line):
    return parse_c_code_token_bytes(line.encode("utf-8", "surrogateescape"))


def parse_font(data, is_tlf):
    font = Font()
    font.is_tlf = is_tlf
    reader = LineReader(data, is_tlf)
    first = reader.next_line()
    if first is None:
        return None
    if is_tlf:
        if not isinstance(first, str) or not first.startswith("tlf2"):
            return None
        if len(first) < 6:
            return None
        font.hardblank = ord(first[5])
        ints = parse_ints_text(first, 6)
    else:
        if not isinstance(first, (bytes, bytearray)) or not first.startswith(b"flf2"):
            return None
        if len(first) < 6:
            return None
        font.hardblank = first[5]
        ints = parse_ints_bytes(bytes(first), 6)
    if len(ints) < 5:
        return None
    height, baseline, maxlen, old_layout, comment_lines = ints[:5]
    font.height = height
    font.old_layout = old_layout
    if len(ints) > 5:
        font.print_direction = ints[5]
    if len(ints) > 6:
        font.full_layout = ints[6]

    read_height = height if height > 0 else 0

    for _ in range(comment_lines if comment_lines > 0 else 0):
        reader.next_line()

    def read_glyph():
        rows = []
        for _ in range(read_height):
            line = reader.next_line()
            if line is None:
                rows.append([])
            else:
                if is_tlf:
                    rows.append(strip_glyph_line_text(line))
                else:
                    rows.append(strip_glyph_line_bytes(bytes(line)))
        return Glyph(rows)

    for code in range(32, 127):
        font.glyphs[code] = read_glyph()

    if reader.has_more():
        for dc in (196, 214, 220, 228, 246, 252, 223):
            font.deutsch[dc] = read_glyph()

        while True:
            code_line = reader.next_line()
            if code_line is None:
                break
            if is_tlf:
                code = parse_c_code_token_text(code_line)
            else:
                code = parse_c_code_token_bytes(bytes(code_line))
            g = read_glyph()
            font.glyphs[code] = g
    return font


def unzip_content(data):
    if data[:4] != b"PK\x03\x04":
        return data
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as z:
            infos = z.infolist()
            if not infos:
                return data
            info = infos[0]
            if info.compress_type != 8:
                return data
            return z.read(info)
    except Exception:
        return data


def read_candidate(path):
    """Return file content bytes if the candidate is selected, else None."""
    try:
        if os.path.isdir(path):
            return b""
    except Exception:
        pass
    try:
        with open(path, "rb") as f:
            return f.read()
    except IsADirectoryError:
        return b""
    except OSError:
        return None
    except ValueError:
        return None


# ---------------------------------------------------------------------------
# Control files

class TranslationTable(object):
    def __init__(self):
        self.map = {}

    def add(self, src, dst):
        if src not in self.map:
            self.map[src] = dst

    def add_range(self, src_first, src_last, dst_first):
        if src_last < src_first:
            return
        # Prevent absurd memory use on pathological ranges; provided
        # control files only use modest ranges.
        for code in range(src_first, src_last + 1):
            if code not in self.map:
                self.map[code] = dst_first + (code - src_first)

    def get(self, code):
        return self.map.get(code, code)


class IsoState(object):
    def __init__(self):
        # Each set is (kind, final); kind is '94', '96' or 'mb'
        self.sets = [("94", 66), ("96", 65), ("94", 66), ("94", 66)]
        self.gl = 0
        self.gr = 1

    def clone(self):
        other = IsoState()
        other.sets = list(self.sets)
        other.gl = self.gl
        other.gr = self.gr
        return other


class ControlParser(object):
    def __init__(self, data, tables, iso_state, holder):
        self.data = data
        self.pos = 0
        self.tables = tables
        self.iso_state = iso_state
        self.holder = holder  # dict with 'mode'

    def current_table(self):
        if not self.tables:
            self.tables.append(TranslationTable())
        return self.tables[-1]

    def new_table(self):
        self.tables.append(TranslationTable())

    def skip_to_eol(self):
        idx = self.data.find(b"\n", self.pos)
        if idx < 0:
            self.pos = len(self.data)
        else:
            self.pos = idx + 1

    def skip_ws_stream(self):
        while self.pos < len(self.data) and self.data[self.pos] in WS_BYTES:
            self.pos += 1

    def parse_number_stream(self):
        """Manual number parser used after a backslash / numeric command."""
        self.skip_ws_stream()
        if self.pos >= len(self.data):
            return None
        sign = 1
        if self.data[self.pos:self.pos + 1] == b"-":
            sign = -1
            self.pos += 1
            if self.pos >= len(self.data) or not (48 <= self.data[self.pos] <= 57):
                return 0
        if self.pos >= len(self.data) or not (48 <= self.data[self.pos] <= 57):
            return None
        if self.data[self.pos:self.pos + 1] != b"0":
            val = 0
            while self.pos < len(self.data) and 48 <= self.data[self.pos] <= 57:
                val = val * 10 + (self.data[self.pos] - 48)
                self.pos += 1
            return sign * val
        # Leading zero: hex or octal (digits 8/9 are treated as octal digits)
        self.pos += 1
        if self.pos < len(self.data) and self.data[self.pos:self.pos + 1] in (b"x", b"X"):
            self.pos += 1
            val = 0
            while self.pos < len(self.data):
                c = self.data[self.pos]
                if 48 <= c <= 57:
                    d = c - 48
                elif 65 <= c <= 70:
                    d = c - 55
                elif 97 <= c <= 102:
                    d = c - 87
                else:
                    break
                val = val * 16 + d
                self.pos += 1
            return sign * val
        val = 0
        while self.pos < len(self.data) and 48 <= self.data[self.pos] <= 57:
            val = val * 8 + (self.data[self.pos] - 48)
            self.pos += 1
        return sign * val

    def read_char_spec(self):
        self.skip_ws_stream()
        if self.pos >= len(self.data):
            return None
        b = self.data[self.pos]
        self.pos += 1
        if b != 92:  # backslash
            return b
        if self.pos >= len(self.data):
            return 0
        c = self.data[self.pos]
        # digit or minus: number
        if (48 <= c <= 57) or c == 45:
            return self.parse_number_stream()
        if c == 120:  # 'x' - historical quirk: value 0, 'x' not consumed
            return 0
        specials = {
            110: 10,  # n
            116: 9,   # t
            114: 13,  # r
            118: 11,  # v
            102: 12,  # f
            97: 7,    # a
            98: 8,    # b
            101: 27,  # e
        }
        self.pos += 1
        if c in specials:
            return specials[c]
        return c

    def parse_translate(self):
        src_first = self.read_char_spec()
        if src_first is None:
            return
        src_last = src_first
        if self.pos < len(self.data) and self.data[self.pos] == 45:
            self.pos += 1
            v = self.read_char_spec()
            if v is not None:
                src_last = v
        dst_first = self.read_char_spec()
        if dst_first is None:
            return
        if self.pos < len(self.data) and self.data[self.pos] == 45:
            self.pos += 1
            self.read_char_spec()  # destination end, ignored
        self.current_table().add_range(src_first, src_last, dst_first)

    def parse_numeric(self):
        src = self.parse_number_stream()
        if src is None:
            return
        dst = self.parse_number_stream()
        if dst is None:
            return
        self.current_table().add(src, dst)

    def parse_g(self):
        self.skip_ws_stream()
        if self.pos >= len(self.data):
            return
        first = self.data[self.pos]
        self.pos += 1
        if 48 <= first <= 51:  # 0-3
            idx = first - 48
            size = self.parse_number_stream()
            if size is None:
                return
            kind = None
            if size == 94:
                kind = "94"
            elif size == 96:
                kind = "96"
            else:
                kind = "94"
            # optional x2 marker for multibyte sets
            if self.data[self.pos:self.pos + 2] in (b"x2", b"X2"):
                self.pos += 2
                kind = "mb"
            final = self.read_char_spec()
            if final is None:
                return
            self.iso_state.sets[idx] = (kind, final)
        elif first in (76, 108):  # L l
            idx = self.parse_number_stream()
            if idx is not None and 0 <= idx <= 3:
                self.iso_state.gl = idx
        elif first in (82, 114):  # R r
            idx = self.parse_number_stream()
            if idx is not None and 0 <= idx <= 3:
                self.iso_state.gr = idx

    def parse(self):
        while self.pos < len(self.data):
            cmd = self.data[self.pos]
            self.pos += 1
            if cmd in (10, 13):
                continue
            if cmd == 35:  # #
                self.skip_to_eol()
            elif cmd == 116:  # t
                self.parse_translate()
                self.skip_to_eol()
            elif cmd == 102:  # f
                self.new_table()
                self.skip_to_eol()
            elif cmd == 103:  # g
                self.parse_g()
                self.skip_to_eol()
            elif cmd == 117:  # u
                self.holder["mode"] = "utf8"
                self.skip_to_eol()
            elif cmd == 104:  # h
                self.holder["mode"] = "hz"
                self.skip_to_eol()
            elif cmd in (98, 106):  # b, j
                self.holder["mode"] = "sjis"
                self.skip_to_eol()
            elif (48 <= cmd <= 57) or cmd == 45:  # digit or '-'
                self.pos -= 1
                self.parse_numeric()
                self.skip_to_eol()
            else:
                self.skip_to_eol()


# ---------------------------------------------------------------------------
# Input decoding

class ByteSource(object):
    def __init__(self, data):
        self.data = data
        self.pos = 0

    def get(self):
        if self.pos >= len(self.data):
            return None
        b = self.data[self.pos]
        self.pos += 1
        return b


class Decoder(object):
    def __init__(self, source, mode, iso_state):
        self.source = source
        self.mode = mode
        self.sets = list(iso_state.sets)
        self.gl = iso_state.gl
        self.gr = iso_state.gr
        self.single_shift = None
        self.gb = False

    def set_code(self, charset, position):
        kind, final = charset
        if kind == "94":
            if final == 66:
                return position
            return (final << 16) | position
        if kind == "96":
            if final == 65:
                return position + 128
            return (final << 16) | position
        return (final << 16) | position

    def handle_escape(self):
        b2 = self.source.get()
        if b2 is None:
            return 255
        if b2 == 36:  # $
            b3 = self.source.get()
            if b3 is None:
                return 511
            if b3 in (40, 41, 42, 43, 45, 46, 47):
                b4 = self.source.get()
                if b4 is None:
                    b4 = 255
                target = {40: 0, 41: 1, 42: 2, 43: 3, 45: 1, 46: 2, 47: 3}[b3]
                self.sets[target] = ("mb", b4)
                return None
            if 64 <= b3 <= 126:
                self.sets[0] = ("mb", b3)
                return None
            return 256 + b3
        if b2 in (40, 41, 42, 43):
            final = self.source.get()
            if final is None:
                final = 255
            self.sets[b2 - 40] = ("94", final)
            return None
        if b2 in (45, 46, 47):
            final = self.source.get()
            if final is None:
                final = 255
            target = {45: 1, 46: 2, 47: 3}[b2]
            self.sets[target] = ("96", final)
            return None
        if b2 == 78:  # N
            self.single_shift = 2
            return None
        if b2 == 79:  # O
            self.single_shift = 3
            return None
        if b2 == 110:  # n
            self.gl = 2
            self.single_shift = None
            return None
        if b2 == 111:  # o
            self.gl = 3
            self.single_shift = None
            return None
        if b2 == 126:  # ~
            self.gr = 1
            return None
        if b2 == 125:  # }
            self.gr = 2
            return None
        if b2 == 124:  # |
            self.gr = 3
            return None
        return 256 + b2

    def next_iso(self):
        while True:
            b = self.source.get()
            if b is None:
                return None
            if b == 14:
                self.gl = 1
                self.single_shift = None
                continue
            if b == 15:
                self.gl = 0
                self.single_shift = None
                continue
            if b == 27:
                code = self.handle_escape()
                if code is None:
                    continue
                return code
            if b == 142:
                self.single_shift = 2
                continue
            if b == 143:
                self.single_shift = 3
                continue
            if b < 32 or b == 127:
                self.single_shift = None
                return b
            if b == 32:
                self.single_shift = None
                return 32
            if b < 128:
                position = b
                if self.single_shift is not None:
                    charset = self.sets[self.single_shift]
                else:
                    charset = self.sets[self.gl]
            else:
                position = b - 128
                if self.single_shift is not None:
                    charset = self.sets[self.single_shift]
                else:
                    charset = self.sets[self.gr]
            self.single_shift = None
            if charset[0] == "mb":
                b2 = self.source.get()
                if b2 is None:
                    position2 = 255
                else:
                    position2 = b2 & 0x7F
                return (charset[1] << 16) | (position << 8) | position2
            return self.set_code(charset, position)

    def next_utf8(self):
        b = self.source.get()
        if b is None:
            return None
        if b < 128:
            return b
        if 192 <= b <= 223:
            need = 1
            code = b & 31
        elif 224 <= b <= 239:
            need = 2
            code = b & 15
        elif 240 <= b <= 247:
            need = 3
            code = b & 7
        elif 248 <= b <= 251:
            need = 4
            code = b & 3
        elif 252 <= b <= 253:
            need = 5
            code = b & 1
        else:
            return 128
        for _ in range(need):
            nb = self.source.get()
            if nb is None:
                nb = 255
            code = (code << 6) | (nb & 63)
        return code

    def next_hz(self):
        while True:
            b = self.source.get()
            if b is None:
                return None
            if not self.gb:
                if b == 126:
                    b2 = self.source.get()
                    if b2 is None:
                        return None
                    if b2 == 123:  # {
                        self.gb = True
                        continue
                    if b2 == 125:  # }
                        continue
                    if b2 == 126:  # ~
                        return 126
                    if b2 == 10:
                        continue
                    continue
                return b
            else:
                b2 = self.source.get()
                if b2 is None:
                    b2 = 255
                return (b << 8) | b2

    def next_sjis(self):
        b = self.source.get()
        if b is None:
            return None
        if (128 <= b <= 159) or (224 <= b <= 239):
            b2 = self.source.get()
            if b2 is None:
                b2 = 255
            return (b << 8) | b2
        return b

    def next_code(self):
        if self.mode == "utf8":
            return self.next_utf8()
        if self.mode == "hz":
            return self.next_hz()
        if self.mode == "sjis":
            return self.next_sjis()
        return self.next_iso()


DEUTSCH_MAP = {
    91: 196,   # [
    92: 214,   # backslash
    93: 220,   # ]
    123: 228,  # {
    124: 246,  # |
    125: 252,  # }
    126: 223,  # ~
}


class ProcessedInput(object):
    def __init__(self, decoder, tables, deutsch, paragraph):
        self.decoder = decoder
        self.tables = tables
        self.deutsch = deutsch
        self.paragraph = paragraph
        self.buffered = self._UNSET = object()
        self.prev = None

    def next_basic(self):
        while True:
            code = self.decoder.next_code()
            if code is None:
                return None
            if self.deutsch and code in DEUTSCH_MAP:
                code = DEUTSCH_MAP[code]
            for table in self.tables:
                code = table.get(code)
            if code == 9:
                return 32
            if code in (11, 12, 13):
                return 10
            if code == 10:
                return 10
            if (1 <= code <= 31) or code == 127:
                continue
            return code

    def next_char(self):
        if self.buffered is not self._UNSET:
            c = self.buffered
            self.buffered = self._UNSET
        else:
            c = self.next_basic()
        if self.paragraph and c == 10:
            peek = self.next_basic()
            self.buffered = peek
            if self.prev != 10 and peek != 32 and peek != 10:
                self.prev = 32
                return 32
            self.prev = 10
            return 10
        self.prev = c
        return c


# ---------------------------------------------------------------------------
# Rendering

UNDERSCORE_SET = set(b"|/\\[]{}()<>")
HIERARCHY = {}
for _i, _grp in enumerate([b"|", b"/\\", b"[]", b"{}", b"()", b"<>"]):
    for _c in _grp:
        HIERARCHY[_c] = _i


def smushem_control(left, right, rules, hardblank):
    if rules & 1:
        if left == right and left != hardblank:
            return left
    if rules & 2:
        if left == 95 and right in UNDERSCORE_SET:
            return right
        if right == 95 and left in UNDERSCORE_SET:
            return left
    if rules & 4:
        lc = HIERARCHY.get(left)
        rc = HIERARCHY.get(right)
        if lc is not None and rc is not None and lc != rc:
            return left if lc > rc else right
    if rules & 8:
        if (left, right) in ((91, 93), (93, 91), (123, 125), (125, 123),
                             (40, 41), (41, 40)):
            return 124
    if rules & 16:
        if left == 47 and right == 92:
            return 124
        if left == 92 and right == 47:
            return 89
        if left == 62 and right == 60:
            return 88
    if rules & 32:
        if left == hardblank and right == hardblank:
            return hardblank
    return None


class FigRenderer(object):
    def __init__(self, font, mode_type, rules, direction, output_width,
                 justification):
        self.font = font
        self.mode_type = mode_type
        self.rules = rules
        self.direction = direction
        self.output_width = output_width
        self.justification = justification
        self.height = font.height if font.height > 0 else 0
        self.rows = [[] for _ in range(self.height)]
        self.length = 0
        self.breakpoint = None
        self.word = []
        self.skip_spaces = False
        self.output = bytearray()

    def get_glyph(self, code):
        if code in self.font.glyphs:
            return self.font.glyphs[code]
        if code >= 0 and code in self.font.deutsch:
            return self.font.deutsch[code]
        if 0 in self.font.glyphs:
            return self.font.glyphs[0]
        return None

    def encode_codes(self, codes):
        if self.font.is_tlf:
            parts = []
            for c in codes:
                if c == self.font.hardblank:
                    c = 32
                try:
                    parts.append(chr(c).encode("utf-8"))
                except Exception:
                    parts.append(b" ")
            return b"".join(parts)
        out = bytearray()
        for c in codes:
            if c == self.font.hardblank:
                c = 32
            out.append(c & 0xFF)
        return bytes(out)

    def effective_justification(self):
        if self.justification == 0:
            return 0
        if self.justification == 1:
            return 1
        if self.justification == 2:
            return 2
        return 0 if self.direction == 0 else 2

    def flush_rows(self, rows, length):
        just = self.effective_justification()
        for row in rows:
            content = list(row)
            if len(content) < length:
                content.extend([32] * (length - len(content)))
            else:
                content = content[:length]
            if just == 1:
                diff = self.output_width - length
                pad = diff // 2 if diff >= 0 else -((-diff) // 2)
                if pad < 0:
                    pad = 0
            elif just == 2:
                pad = self.output_width - 1 - length
                if pad < 0:
                    pad = 0
            else:
                pad = 0
            codes = [32] * pad + content
            if self.output_width != 1:
                codes = codes[:max(self.output_width - 1, 0)]
            self.output.extend(self.encode_codes(codes))
            self.output.append(10)

    def flush_current(self):
        self.flush_rows(self.rows, self.length)

    def reset_line(self):
        self.rows = [[] for _ in range(self.height)]
        self.length = 0
        self.breakpoint = None
        self.word = []

    def compute_amount(self, glyph):
        if self.mode_type == "full" or glyph.width == 0 or self.height == 0:
            return 0
        amounts = []
        for i in range(self.height):
            cur_row = self.rows[i]
            grow = glyph.rows[i] if i < len(glyph.rows) else []
            char_row = list(grow) + [32] * (glyph.width - len(grow))
            if self.direction == 0:
                trailing = 0
                for c in reversed(cur_row):
                    if c == 32:
                        trailing += 1
                    else:
                        break
                leading = 0
                for c in char_row:
                    if c == 32:
                        leading += 1
                    else:
                        break
                amount = trailing + leading
                cur_b = None
                for c in reversed(cur_row):
                    if c != 32:
                        cur_b = c
                        break
                char_b = None
                for c in char_row:
                    if c != 32:
                        char_b = c
                        break
            else:
                leading_cur = 0
                for c in cur_row:
                    if c == 32:
                        leading_cur += 1
                    else:
                        break
                trailing_char = 0
                for c in reversed(char_row):
                    if c == 32:
                        trailing_char += 1
                    else:
                        break
                amount = leading_cur + trailing_char
                cur_b = None
                for c in cur_row:
                    if c != 32:
                        cur_b = c
                        break
                char_b = None
                for c in reversed(char_row):
                    if c != 32:
                        char_b = c
                        break
            if (self.mode_type in ("controlled", "universal")
                    and glyph.width > 1 and cur_b is not None
                    and char_b is not None):
                if self.mode_type == "universal":
                    amount += 1
                else:
                    if self.direction == 0:
                        left, right = cur_b, char_b
                    else:
                        left, right = char_b, cur_b
                    if smushem_control(left, right, self.rules,
                                       self.font.hardblank) is not None:
                        amount += 1
            amounts.append(amount)
        amount = min(amounts) if amounts else 0
        if amount > glyph.width:
            amount = glyph.width
        if amount < 0:
            amount = 0
        return amount

    def merge_code(self, existing, incoming):
        if existing == 32:
            return incoming
        if incoming == 32:
            return existing
        if self.mode_type == "universal":
            if incoming == self.font.hardblank:
                return existing
            return incoming
        if self.mode_type == "controlled":
            if self.direction == 0:
                left, right = existing, incoming
            else:
                left, right = incoming, existing
            res = smushem_control(left, right, self.rules,
                                  self.font.hardblank)
            if res is not None:
                return res
            return incoming
        return incoming

    def add_glyph(self, glyph, amount):
        if glyph.width == 0 or self.height == 0:
            return
        new_length = self.length + glyph.width - amount
        if new_length < 0:
            new_length = 0
        new_rows = []
        if self.direction == 0:
            start = self.length - amount
            for i in range(self.height):
                new_row = [32] * new_length
                for j in range(min(self.length, new_length)):
                    new_row[j] = self.rows[i][j]
                grow = glyph.rows[i] if i < len(glyph.rows) else []
                char_row = list(grow) + [32] * (glyph.width - len(grow))
                for j, ch in enumerate(char_row):
                    pos = start + j
                    if 0 <= pos < new_length:
                        new_row[pos] = self.merge_code(new_row[pos], ch)
                new_rows.append(new_row)
        else:
            offset = glyph.width - amount
            for i in range(self.height):
                new_row = [32] * new_length
                for j, existing in enumerate(self.rows[i]):
                    pos = offset + j
                    if 0 <= pos < new_length:
                        new_row[pos] = existing
                grow = glyph.rows[i] if i < len(glyph.rows) else []
                char_row = list(grow) + [32] * (glyph.width - len(grow))
                for j, ch in enumerate(char_row):
                    pos = j
                    if 0 <= pos < new_length:
                        new_row[pos] = self.merge_code(new_row[pos], ch)
                new_rows.append(new_row)
        self.rows = new_rows
        self.length = new_length

    def add_nonspace_charbreak_only(self, code):
        glyph = self.get_glyph(code)
        if glyph is None:
            self.word.append(code)
            return
        amount = self.compute_amount(glyph)
        new_length = self.length + glyph.width - amount
        if self.length > 0 and new_length >= self.output_width:
            self.flush_current()
            self.reset_line()
            self.word = [code]
            amount = self.compute_amount(glyph)
            self.add_glyph(glyph, amount)
        else:
            self.word.append(code)
            self.add_glyph(glyph, amount)

    def process_code(self, code):
        if code == 10:
            self.flush_current()
            self.reset_line()
            self.skip_spaces = False
            return
        if self.skip_spaces:
            if code == 32:
                return
            self.skip_spaces = False
        if code == 32:
            if self.word:
                self.breakpoint = ([list(r) for r in self.rows], self.length)
                self.word = []
            glyph = self.get_glyph(code)
            if glyph is None:
                return
            amount = self.compute_amount(glyph)
            new_length = self.length + glyph.width - amount
            if self.length > 0 and new_length >= self.output_width:
                if self.breakpoint is not None:
                    bp_rows, bp_len = self.breakpoint
                    self.flush_rows(bp_rows, bp_len)
                else:
                    self.flush_current()
                self.reset_line()
                self.skip_spaces = True
                return
            self.add_glyph(glyph, amount)
            return
        # non-space
        glyph = self.get_glyph(code)
        if glyph is None:
            self.word.append(code)
            return
        amount = self.compute_amount(glyph)
        new_length = self.length + glyph.width - amount
        if self.length > 0 and new_length >= self.output_width:
            if self.breakpoint is not None:
                bp_rows, bp_len = self.breakpoint
                self.flush_rows(bp_rows, bp_len)
                replay = list(self.word) + [code]
                self.reset_line()
                for rc in replay:
                    self.add_nonspace_charbreak_only(rc)
                return
            self.flush_current()
            self.reset_line()
            self.word = [code]
            amount = self.compute_amount(glyph)
            self.add_glyph(glyph, amount)
            return
        self.word.append(code)
        self.add_glyph(glyph, amount)


# ---------------------------------------------------------------------------

def usage_bytes(myname):
    return (b"Usage: " + myname +
            b" [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n"
            b"              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n"
            b"              [ -C controlfile ] [ -I infocode ] [ message ]\n")


def version_bytes(myname):
    return (b"FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,\n"
            b"Christiaan Keet and Claudio Matsuoka\n"
            b"Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012\n"
            b"\n"
            b"FIGlet, along with the various FIGlet fonts and documentation, may be\n"
            b"freely copied and distributed.\n"
            b"\n"
            b"If you use FIGlet, please send an e-mail message to <info@figlet.org>.\n"
            b"\n"
            b"The latest version of FIGlet is available from the web site,\n"
            b"\thttp://www.figlet.org/\n"
            b"\n" + usage_bytes(myname))


def terminal_width():
    if fcntl is None or termios is None:
        return None
    try:
        data = fcntl.ioctl(0, termios.TIOCGWINSZ, b"\x00" * 8)
        _rows, cols, _xp, _yp = struct.unpack("HHHH", data)
        if cols > 0:
            return cols
    except Exception:
        return None
    return None


def font_default_mode(font):
    if font.full_layout is not None:
        h = font.full_layout & 0xFF
        if h & 128:
            rules = h & 63
            return ("controlled", rules) if rules else ("universal", 0)
        if h & 64:
            return ("kern", 0)
        return ("full", 0)
    if font.old_layout < 0:
        return ("full", 0)
    if font.old_layout == 0:
        return ("kern", 0)
    rules = font.old_layout & 63
    return ("controlled", rules) if rules else ("universal", 0)


def font_forced_mode(font):
    if font.full_layout is not None:
        rules = font.full_layout & 63
        return ("controlled", rules) if rules else ("universal", 0)
    if font.old_layout > 0:
        rules = font.old_layout & 63
        return ("controlled", rules) if rules else ("universal", 0)
    return ("universal", 0)


def main(argv):
    argv_b = [os.fsencode(a) for a in argv]
    if argv_b:
        argv0 = argv_b[0]
    else:
        argv0 = b""
    myname = argv0.rsplit(b"/", 1)[-1] if argv0 else b""

    stderr = sys.stderr.buffer
    stdout = sys.stdout.buffer

    # defaults
    fontdir = DEFAULT_FONT_DIR
    fontname = DEFAULT_FONT_NAME
    output_width = 80
    infocode = -1
    justification = 3  # default, by direction
    direction_opt = 2  # 0 = L, 1 = R, 2 = font default (X)
    paragraph = False
    deutsch = False
    layout_override = None  # None, 'force', 'kern', 'full', 'universal', or ('explicit', rules)
    control_names = []
    use_cmdline = False

    posixly = "POSIXLY_CORRECT" in os.environ

    args = argv_b[1:]
    operands = []
    i = 0
    end_options = False
    stop_all = False
    while i < len(args) and not stop_all:
        arg = args[i]
        if end_options:
            operands.append(arg)
            i += 1
            continue
        if arg == b"--":
            end_options = True
            i += 1
            continue
        if len(arg) < 2 or arg[:1] != b"-":
            if posixly:
                # Remaining arguments are all operands.
                operands.extend(args[i:])
                break
            operands.append(arg)
            i += 1
            continue
        # an option cluster
        cluster = arg[1:]
        j = 0
        consumed_next_arg = False
        while j < len(cluster):
            ch = cluster[j]
            c = bytes([ch])
            if ch in b"cklnoprstvxDELNRSWAX":
                if ch == ord('c'):
                    justification = 1
                elif ch == ord('l'):
                    justification = 0
                elif ch == ord('r'):
                    justification = 2
                elif ch == ord('x'):
                    justification = 3
                elif ch == ord('L'):
                    direction_opt = 0
                elif ch == ord('R'):
                    direction_opt = 1
                elif ch == ord('X'):
                    direction_opt = 2
                elif ch == ord('D'):
                    deutsch = True
                elif ch == ord('E'):
                    deutsch = False
                elif ch == ord('n'):
                    paragraph = False
                elif ch == ord('p'):
                    paragraph = True
                elif ch == ord('s'):
                    layout_override = None
                elif ch == ord('S'):
                    layout_override = "force"
                elif ch == ord('k'):
                    layout_override = "kern"
                elif ch == ord('W'):
                    layout_override = "full"
                elif ch == ord('o'):
                    layout_override = "universal"
                elif ch == ord('t'):
                    tw = terminal_width()
                    if tw is not None:
                        output_width = tw
                elif ch == ord('v'):
                    infocode = 0
                elif ch == ord('N'):
                    control_names = []
                elif ch == ord('A'):
                    use_cmdline = True
                elif ch == ord('X'):
                    direction_opt = 2
                j += 1
                continue
            if ch == ord('F'):
                stderr.write(myname + b": illegal option -- F\n")
                stderr.write(usage_bytes(myname))
                stderr.write(b"\nBecause of numerous incompatibilities, the \"-F\" option has been\n"
                             b"removed.  It has been replaced by the \"figlist\" program, which is now\n"
                             b"included in the basic FIGlet package.  \"figlist\" is also available\n"
                             b"from  http://www.figlet.org/under UNIX utilities.\n")
                return 1
            if ch in b"dfmwCI":
                # option with argument
                if j + 1 < len(cluster):
                    optarg = cluster[j + 1:]
                elif i + 1 < len(args):
                    optarg = args[i + 1]
                    consumed_next_arg = True
                else:
                    stderr.write(argv0 + b": option requires an argument -- '" + c + b"'\n")
                    stderr.write(usage_bytes(myname))
                    return 1
                if ch == ord('d'):
                    fontdir = optarg
                elif ch == ord('f'):
                    fontname = strip_suffix(optarg, (b".flf", b".tlf"))
                elif ch == ord('C'):
                    control_names.append(strip_suffix(optarg, (b".flc",)))
                elif ch == ord('I'):
                    infocode = c_atoi(optarg)
                elif ch == ord('w'):
                    v = c_atoi(optarg)
                    if v > 0:
                        output_width = v
                elif ch == ord('m'):
                    v = c_atoi(optarg)
                    if v == -1:
                        layout_override = "full"
                    elif v < -1:
                        layout_override = None
                    elif v == 0:
                        layout_override = "kern"
                    else:
                        rules = v & 63
                        layout_override = ("explicit", rules)
                j = len(cluster)
                break
            # invalid option
            stderr.write(argv0 + b": invalid option -- '" + c + b"'\n")
            stderr.write(usage_bytes(myname))
            return 1
        i += 2 if consumed_next_arg else 1

    if use_cmdline:
        pass
    elif operands:
        use_cmdline = True

    # Information requests are handled before loading anything.
    if infocode >= 0:
        if infocode == 0:
            stdout.write(version_bytes(myname))
        elif infocode == 1:
            stdout.write(b"%d\n" % VERSION_INT)
        elif infocode == 2:
            stdout.write(fontdir + b"\n")
        elif infocode == 3:
            stdout.write(fontname + b"\n")
        elif infocode == 4:
            stdout.write(b"%d\n" % output_width)
        elif infocode == 5:
            stdout.write(b"flf2 tlf2\n")
        return 0

    # Load control files, in order; failures precede font errors.
    tables = []
    iso_state = IsoState()
    holder = {"mode": "iso"}
    for ctlname in control_names:
        candidates = [fontdir + b"/" + ctlname + b".flc", ctlname + b".flc"]
        content = None
        for cand in candidates:
            content = read_candidate(cand)
            if content is not None:
                break
        if content is None:
            stderr.write(myname + b": " + ctlname + b": Unable to open control file\n")
            return 1
        content = unzip_content(content)
        tables.append(TranslationTable())
        parser = ControlParser(content, tables, iso_state, holder)
        parser.parse()

    # Load font.
    candidates = [
        (fontdir + b"/" + fontname + b".flf", False),
        (fontname + b".flf", False),
        (fontdir + b"/" + fontname + b".tlf", True),
        (fontname + b".tlf", True),
    ]
    font = None
    for cand, is_tlf in candidates:
        content = read_candidate(cand)
        if content is None:
            continue
        content = unzip_content(content)
        font = parse_font(content, is_tlf)
        if font is None:
            stderr.write(myname + b": " + fontname + b": Not a FIGlet 2 font file\n")
            return 1
        break
    if font is None:
        stderr.write(myname + b": " + fontname + b": Unable to open font file\n")
        return 1

    # Effective direction and layout.
    if direction_opt == 0:
        direction = 0
    elif direction_opt == 1:
        direction = 1
    else:
        direction = 1 if font.print_direction != 0 else 0

    if layout_override is None:
        mode_type, rules = font_default_mode(font)
    elif layout_override == "force":
        mode_type, rules = font_forced_mode(font)
    elif layout_override == "kern":
        mode_type, rules = "kern", 0
    elif layout_override == "full":
        mode_type, rules = "full", 0
    elif layout_override == "universal":
        mode_type, rules = "universal", 0
    else:  # explicit
        _tag, rules_val = layout_override
        if rules_val == 0:
            mode_type, rules = "universal", 0
        else:
            mode_type, rules = "controlled", rules_val

    # Input bytes.
    if use_cmdline:
        buf = bytearray()
        for idx, word in enumerate(operands):
            buf.extend(word)
            if idx < len(operands) - 1:
                if len(word) == 0:
                    buf.append(10)
                else:
                    buf.append(32)
        input_data = bytes(buf)
    else:
        try:
            input_data = sys.stdin.buffer.read()
        except Exception:
            input_data = b""
        if input_data is None:
            input_data = b""

    decoder = Decoder(ByteSource(input_data), holder["mode"], iso_state.clone())
    processed = ProcessedInput(decoder, tables, deutsch, paragraph)
    renderer = FigRenderer(font, mode_type, rules, direction, output_width,
                           justification)
    while True:
        code = processed.next_char()
        if code is None:
            break
        renderer.process_code(code)
    if renderer.length > 0:
        renderer.flush_current()
    stdout.write(renderer.output)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        sys.exit(1)
