# Input decoding

class ByteSource(object):
    def __init__(self, data):
        self.data = data
        self.pos = 0

    def get(self):
        if self.pos >= len(self.data):
            return None
        b = self.data[self.pos]
        self.pos += 1
        return b


class Decoder(object):
    def __init__(self, source, mode, iso_state):
        self.source = source
        self.mode = mode
        self.sets = list(iso_state.sets)
        self.gl = iso_state.gl
        self.gr = iso_state.gr
        self.single_shift = None
        self.gb = False

    def set_code(self, charset, position):
        kind, final = charset
        if kind == "94":
            if final == 66:
                return position
            return (final << 16) | position
        if kind == "96":
            if final == 65:
                return position + 128
            return (final << 16) | position
        return (final << 16) | position

    def handle_escape(self):
        b2 = self.source.get()
        if b2 is None:
            return 255
        if b2 == 36:  # $
            b3 = self.source.get()
            if b3 is None:
                return 511
            if b3 in (40, 41, 42, 43, 45, 46, 47):
                b4 = self.source.get()
                if b4 is None:
                    b4 = 255
                target = {40: 0, 41: 1, 42: 2, 43: 3, 45: 1, 46: 2, 47: 3}[b3]
                self.sets[target] = ("mb", b4)
                return None
            if 64 <= b3 <= 126:
                self.sets[0] = ("mb", b3)
                return None
            return 256 + b3
        if b2 in (40, 41, 42, 43):
            final = self.source.get()
            if final is None:
                final = 255
            self.sets[b2 - 40] = ("94", final)
            return None
        if b2 in (45, 46, 47):
            final = self.source.get()
            if final is None:
                final = 255
            target = {45: 1, 46: 2, 47: 3}[b2]
            self.sets[target] = ("96", final)
            return None
        if b2 == 78:  # N
            self.single_shift = 2
            return None
        if b2 == 79:  # O
            self.single_shift = 3
            return None
        if b2 == 110:  # n
            self.gl = 2
            self.single_shift = None
            return None
        if b2 == 111:  # o
            self.gl = 3
            self.single_shift = None
            return None
        if b2 == 126:  # ~
            self.gr = 1
            return None
        if b2 == 125:  # }
            self.gr = 2
            return None
        if b2 == 124:  # |
            self.gr = 3
            return None
        return 256 + b2

    def next_iso(self):
        while True:
            b = self.source.get()
            if b is None:
                return None
            if b == 14:
                self.gl = 1
                self.single_shift = None
                continue
            if b == 15:
                self.gl = 0
                self.single_shift = None
                continue
            if b == 27:
                code = self.handle_escape()
                if code is None:
                    continue
                return code
            if b == 142:
                self.single_shift = 2
                continue
            if b == 143:
                self.single_shift = 3
                continue
            if b < 32 or b == 127:
                self.single_shift = None
                return b
            if b == 32:
                self.single_shift = None
                return 32
            if b < 128:
                position = b
                if self.single_shift is not None:
                    charset = self.sets[self.single_shift]
                else:
                    charset = self.sets[self.gl]
            else:
                position = b - 128
                if self.single_shift is not None:
                    charset = self.sets[self.single_shift]
                else:
                    charset = self.sets[self.gr]
            self.single_shift = None
            if charset[0] == "mb":
                b2 = self.source.get()
                if b2 is None:
                    position2 = 255
                else:
                    position2 = b2 & 0x7F
                return (charset[1] << 16) | (position << 8) | position2
            return self.set_code(charset, position)

    def next_utf8(self):
        b = self.source.get()
        if b is None:
            return None
        if b < 128:
            return b
        if 192 <= b <= 223:
            need = 1
            code = b & 31
        elif 224 <= b <= 239:
            need = 2
            code = b & 15
        elif 240 <= b <= 247:
            need = 3
            code = b & 7
        elif 248 <= b <= 251:
            need = 4
            code = b & 3
        elif 252 <= b <= 253:
            need = 5
            code = b & 1
        else:
            return 128
        for _ in range(need):
            nb = self.source.get()
            if nb is None:
                nb = 255
            code = (code << 6) | (nb & 63)
        return code

    def next_hz(self):
        while True:
            b = self.source.get()
            if b is None:
                return None
            if not self.gb:
                if b == 126:
                    b2 = self.source.get()
                    if b2 is None:
                        return None
                    if b2 == 123:  # {
                        self.gb = True
                        continue
                    if b2 == 125:  # }
                        continue
                    if b2 == 126:  # ~
                        return 126
                    if b2 == 10:
                        continue
                    continue
                return b
            else:
                b2 = self.source.get()
                if b2 is None:
                    b2 = 255
                return (b << 8) | b2

    def next_sjis(self):
        b = self.source.get()
        if b is None:
            return None
        if (128 <= b <= 159) or (224 <= b <= 239):
            b2 = self.source.get()
            if b2 is None:
                b2 = 255
            return (b << 8) | b2
        return b

    def next_code(self):
        if self.mode == "utf8":
            return self.next_utf8()
        if self.mode == "hz":
            return self.next_hz()
        if self.mode == "sjis":
            return self.next_sjis()
        return self.next_iso()


DEUTSCH_MAP = {
    91: 196,   # [
    92: 214,   # backslash
    93: 220,   # ]
    123: 228,  # {
    124: 246,  # |
    125: 252,  # }
    126: 223,  # ~
}


class ProcessedInput(object):
    def __init__(self, decoder, tables, deutsch, paragraph):
        self.decoder = decoder
        self.tables = tables
        self.deutsch = deutsch
        self.paragraph = paragraph
        self.buffered = self._UNSET = object()
        self.prev = None

    def next_basic(self):
        while True:
            code = self.decoder.next_code()
            if code is None:
                return None
            if self.deutsch and code in DEUTSCH_MAP:
                code = DEUTSCH_MAP[code]
            for table in self.tables:
                code = table.get(code)
            if code == 9:
                return 32
            if code in (11, 12, 13):
                return 10
            if code == 10:
                return 10
            if (1 <= code <= 31) or code == 127:
                continue
            return code

    def next_char(self):
        if self.buffered is not self._UNSET:
            c = self.buffered
            self.buffered = self._UNSET
        else:
            c = self.next_basic()
        if self.paragraph and c == 10:
            peek = self.next_basic()
            self.buffered = peek
            if self.prev != 10 and peek != 32 and peek != 10:
                self.prev = 32
                return 32
            self.prev = 10
            return 10
        self.prev = c
        return c


