                return data
            info = infos[0]
            if info.compress_type != 8:
                return data
            return z.read(info)
    except Exception:
        return data


def read_candidate(path):
    """Return file content bytes if the candidate is selected, else None."""
    try:
        if os.path.isdir(path):
            return b""
    except Exception:
        pass
    try:
        with open(path, "rb") as f:
            return f.read()
    except IsADirectoryError:
        return b""
    except OSError:
        return None
    except ValueError:
        return None


